def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if write_time + ttl <= t:
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]

        if op[0] == 'put':
            key, value = op[2], op[3]

            # If key exists, remove it (we'll re-add it at the end)
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is new, evict LRU
            elif len(cache) >= capacity:
                # Remove the first (least recently used) item
                cache.popitem(last=False)

            # Add the new entry (most recently used)
            cache[key] = (value, t)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Make it most recently used by removing and re-adding
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

